CREATE TABLE "ai_call_metrics" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "request_id" uuid NOT NULL REFERENCES "pricing_workflow_requests"("id"), "recommendation_id" uuid REFERENCES "pricing_recommendations"("id"), "model" text NOT NULL, "prompt_version" text NOT NULL, "input_tokens" integer, "output_tokens" integer, "estimated_cost_usd" numeric(10,6), "latency_ms" integer NOT NULL, "success" integer NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
